  "confidence": 0.96,
  "anomalies": [
    {
      "category": "bridged_nets",
      "components": ["R4"],
      "pins": ["J11.3", "J7.3", "R4.1", "R4.2"],
      "nets": ["Net-(J11-Pin_3)", "Net-(J7-Pin_3)"],
      "observed": "R4 is a 0 Ω resistor directly connecting the two servo signal pins: R4.1 is on Net-(J11-Pin_3) and R4.2 is on Net-(J7-Pin_3).",
      "expected": "In PWM mode the two servo headers must have independent signal lines. The specification says they are bridged only in serial mode by populating R13/R14; they should not be permanently connected through R4.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(comp (ref \"R4\") (value \"0\")"
        },
        {
          "source": "netlist",
          "quote": "(node (ref \"R4\") (pin \"2\")) ... (name \"Net-(J7-Pin_3)\")"
        },
        {
          "source": "netlist",
          "quote": "(node (ref \"R4\") (pin \"1\")) ... (name \"Net-(J11-Pin_3)\")"
        },
        {
          "source": "spec",
          "quote": "PWM mode: two independent PWM channels"
        },
        {
          "source": "spec",
          "quote": "Serial mode ... Short R13, R14 ... bridge J3-pin3 and J8-pin3 together"
        }
      ],
      "impact": "The servo signal outputs are electrically tied together, so PWM mode cannot independently control the two servos; the shared signal can also cause contention between their GPIO drivers.",
      "confidence": 0.96
    }
  ],
  "summary": "The netlist shows a 0 Ω link directly joining the two servo signal pins. This contradicts the specified independent PWM channels and makes the signal paths shared regardless of the intended serial-mode jumper selection."
}

